import java.util.*;

public class Main {
    static class Edge {
        int to, cap, cost, rev;
        Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static final int maxn = 6000;
    static final int inf = Integer.MAX_VALUE;
    static final long inff = 1000000000000000000L;
    static List<Edge>[] graph = new ArrayList[maxn];
    static long[] dist = new long[maxn];
    static int[] parent_node = new int[maxn];
    static int[] parent_edge = new int[maxn];
    static boolean[] in_queue = new boolean[maxn];

    static int total_nodes, s, t;

    static void setup(int _nodes, int _source, int _sink) {
        for (int i = 0; i <= _nodes; i++) {
            graph[i] = new ArrayList<>();
        }
        total_nodes = _nodes;
        s = _source;
        t = _sink;
    }

    static void add_link(int from, int to, int capacity, int cost) {
        graph[from].add(new Edge(to, capacity, cost, graph[to].size()));
        graph[to].add(new Edge(from, 0, -cost, graph[from].size() - 1));
    }

    static long min_cost_max_flow(int flow_needed) {
        long total_cost = 0;
        while (flow_needed > 0) {
            Arrays.fill(dist, 0, total_nodes, inff);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            Arrays.fill(in_queue, 0, total_nodes, false);
            in_queue[s] = true;

            while (!q.isEmpty()) {
                int u = q.poll();
                in_queue[u] = false;
                for (int i = 0; i < graph[u].size(); i++) {
                    Edge e = graph[u].get(i);
                    if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        parent_node[e.to] = u;
                        parent_edge[e.to] = i;
                        if (!in_queue[e.to]) {
                            in_queue[e.to] = true;
                            q.offer(e.to);
                        }
                    }
                }
            }

            if (dist[t] == inff) return -1;

            int flow_delta = flow_needed;
            for (int v = t; v != s; v = parent_node[v]) {
                flow_delta = Math.min(flow_delta, graph[parent_node[v]].get(parent_edge[v]).cap);
            }
            flow_needed -= flow_delta;
            total_cost += (long) flow_delta * dist[t];
            for (int v = t; v != s; v = parent_node[v]) {
                Edge e = graph[parent_node[v]].get(parent_edge[v]);
                e.cap -= flow_delta;
                graph[v].get(e.rev).cap += flow_delta;
            }
        }
        return total_cost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int[] A = new int[58];
        List<Integer>[] H = new ArrayList[57];
        for (int i = 0; i < H.length; i++) {
            H[i] = new ArrayList<>();
        }

        for (int i = 1; i <= K; i++) {
            int X = sc.nextInt();
            A[X]++;
        }

        for (int i = 1; i <= M; i++) {
            int X = sc.nextInt();
            int Y = sc.nextInt();
            H[X].add(Y);
            H[Y].add(X);
        }

        setup(5103, 0, 5101);
        for (int i = 2; i <= N; i++) {
            add_link(0, i, A[i], 0);
        }

        for (int i = 0; i <= 100; i++) {
            for (int l = 1; l <= N; l++) {
                add_link(50 * i + l, 50 * (i + 1) + l, K, 0);
                for (int j : H[l]) {
                    for (int k = 1; k <= K; k++) {
                        add_link(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                    }
                }
            }
        }

        for (int i = 1; i <= 101; i++) {
            add_link(50 * i + 1, 5101, K, C * i);
        }

        System.out.println(min_cost_max_flow(K));
        sc.close();
    }
}
